 up = draggedOrigin(start:start,pointerStart:anchor,pointer:NSPoint(x:360,y:450))\n    precondition(up == NSPoint(x:310,y:400), \"Upward drag must move upward\")\n    let down = draggedOrigin(start:start,pointerStart:anchor,pointer:NSPoint(x:250,y:50))\n    precondition(down == NSPoint(x:200,y:0), \"Downward drag delta must not flip\")\n    let clip = Clip(frames:[\"a\",\"b\",\"c\"],durations:[280,110,320])\n    precondition(clip.frame(at:280)==\"b\" && clip.frame(at:390)==\"c\" && clip.frame(at:710)==\"a\")\n    var deck = ActionDeck()\n    let pool: Set<String> = [\"GREET\", \"BOUNCE\", \"WALK_r\", \"WALK_l\"]\n    let cycle = (0..<4).map { _ in deck.next(available:pool,pinned:false) }\n    precondition(Set(cycle) == pool, \"Each available action appears once per cycle\")\n    for _ in 0..<20 { precondition(!deck.next(available:pool,pinned:true).hasPrefix(\"WALK_\")) }\n    precondition(deck.next(available:[],pinned:true) == \"IDLE\")\n    // 宿主桥接归约器：主场景重放（与 tests/test_host_bridge.py 同语义）\n    do {\n        let tmp = FileManager.default.temporaryDirectory\n            .appendingPathComponent(\"comi-selftest-\\(UUID().uuidString)\")\n        try FileManager.default.createDirectory(at: tmp, withIntermediateDirectories: true)\n        defer { try? FileManager.default.removeItem(at: tmp) }\n        let epoch = 1_800_000_000.0\n        var tick = epoch\n        let bridge = HostBridge(directory: tmp, clock: { tick })\n        var emission = 0\n        func emit(_ kind: String, session: String = \"s1\", label: String? = nil, source: String = \"test\") throws {\n            emission += 1\n            let iso = ISO8601DateFormatter()\n            let text = \"\"\"\n            {\"version\":1,\"event_id\":\"\\(source)-\\(kind)-\\(session)-\\(emission)\",\"source\":\"\\(source)\",\"session_id\":\"\\(session)\",\"turn_id\":null,\"timestamp\":\"\\(iso.string(from: Date(timeIntervalSince1970: tick)))\",\"kind\":\"\\(kind)\",\"task_label\":\\(label.map { \"\\\"\\($0)\\\"\" } ?? \"null\"),\"summary\":null,\"tool_name\":null,\"severity\":\"info\"}\n            \"\"\"\n            try text.write(to: tmp.appendingPathComponent(\"\\(tick)-\\(String(format:\"%06d\",emission))-\\(kind).json\"), atomically: true, encoding: .utf8)\n        }\n        try emit(\"session.started\"); try emit(\"turn.started\", label: \"运行测试\")\n        _ = bridge.poll()\n        precondition(bridge.mode == \"working\" && bridge.label == \"运行测试\", \"turn.started → working + label\")\n        try emit(\"permission.required\")\n        let ns = bridge.poll()\n        precondition(bridge.mode == \"waiting\" && ns.contains { $0.kind == \"permission.required\" }, \"permission → waiting + notice\")\n        tick += 2\n        try emit(\"tool.finished\")\n        _ = bridge.poll()\n        precondition(bridge.mode == \"working\", \"tool.finished after approval → back to working\")\n        try emit(\"turn.ended\")\n        let ns2 = bridge.poll()\n        precondition(ns2.contains { $0.kind == \"turn.ended\" } && !ns2.contains { $0.kind == \"task.completed\" }, \"Stop is not success\")\n        precondition(bridge.mode == nil, \"turn end → back to normal rotation\")\n        try emit(\"turn.started\", session: \"a\"); try emit(\"turn.started\", session: \"b\")\n        _ = bridge.poll()\n        try emit(\"turn.ended\", session: \"a\")\n        _ = bridge.poll()\n        precondition(bridge.mode == \"working\", \"parallel sessions stay working until all end\")\n        tick += HostBridge.sessionQuiet + 1\n        _ = bridge.poll()\n        precondition(bridge.mode == nil, \"quiet session decays to idle (not pinned)\")\n        tick += HostBridge.staleAfter + 1\n        _ = bridge.poll()\n        precondition(bridge.mode == nil, \"disconnect falls back silently\")\n        try emit(\"turn.started\",session:\"same\",source:\"zcode\")\n        try emit(\"turn.started\",session:\"same\",source:\"dsh\")\n        _ = bridge.poll()\n        precondition(bridge.activeSources == [\"dsh\",\"zcode\"] && bridge.source == \"dsh\", \"Sources must not collide on a shared session id\")\n        try emit(\"permission.required\",session:\"same\",source:\"zcode\")\n        _ = bridge.poll()\n        precondition(bridge.source == \"zcode\", \"Badge follows the waiting harness\")\n        bridge.selectedSource = \"dsh\"\n        precondition(bridge.source == \"dsh\" && bridge.mode == \"working\", \"Explicit source overrides other waiting hosts\")\n        precondition(bridge.sourceStatus(\"zcode\") == \"等你确认\" && bridge.sourceStatus(\"codex\") == \"未收到事件\", \"Menu shows actual received state\")\n        try emit(\"turn.ended\",session:\"same\",source:\"zcode\")\n        precondition(bridge.poll().isEmpty && bridge.source == \"dsh\", \"Other hosts cannot interrupt selected source\")\n        bridge.selectedSource = \"codex\"\n        precondition(bridge.mode == nil && bridge.source == nil, \"Unconnected selection cannot inherit another host\")\n        bridge.selectedSource = nil\n        try emit(\"session.ended\",session:\"same\",source:\"zcode\")\n        _ = bridge.poll()\n        precondition(bridge.source == \"dsh\", \"Closing one harness does not clear another\")\n        let leftovers = (try? FileManager.default.contentsOfDirectory(atPath: tmp.path)) ?? [\"<unreadable>\"]\n        precondition(leftovers.isEmpty, \"inbox consumed cleanly\")\n    } catch {\n        fputs(\"bridge self-test threw: \\(error)\\n\", stderr)\n        exit(1)\n    }\n    // 甩抛物理（与 tests/test_throw_physics.py 同语义；Cocoa y 向上）\n    do {\n        let v = ThrowPhysics.estimateVelocity(samples: [(10.0,0,0),(10.1,500,0),(10.15,550,0)], now: 10.15)\n        precondition(v != nil && abs(v!.vx - 1000) < 0.01, \"stale samples outside the window are ignored\")\n        precondition(ThrowPhysics.estimateVelocity(samples: [(10.0,0,0),(10.005,30,0)], now: 10.005) == nil,\n                     \"span shorter than minSpan has no velocity\")\n        let fly = ThrowPhysics.step(x: 500, y: 400, vx: 100, vy: 800, dt: 0.05,\n                                    minX: 0, maxX: 1800, maxY: 1000, floorY: 0, size: 200)\n        precondition(fly.event == \"fly\" && fly.y > 400, \"still rising\")\n        let hit = ThrowPhysics.step(x: 500, y: 2, vx: 0, vy: -1500, dt: 0.05,\n                                    minX: 0, maxX: 1800, maxY: 1000, floorY: 0, size: 200)\n        precondition(hit.event == \"bounce\" && hit.y == 0 && hit.vy > 0 && hit.vy < 1560,\n                     \"floor bounce reflects upward with energy loss\")\n        let soft = ThrowPhysics.step(x: 500, y: 0, vx: 50, vy: -100, dt: 0.05,\n                                     minX: 0, maxX: 1800, maxY: 1000, floorY: 0, size: 200)\n        precondition(soft.event == \"land\" && soft.vx == 0 && soft.vy == 0, \"soft contact settles in place\")\n        let wall = ThrowPhysics.step(x: 1790, y: 500, vx: 3000, vy: 0, dt: 0.05,\n                                     minX: 0, maxX: 1800, maxY: 1000, floorY: 0, size: 200)\n        precondition(wall.x == 1800 && wall.vx < 0, \"right edge reflects the throw\")\n        let ceiling = ThrowPhysics.step(x: 500, y: 799, vx: 0, vy: 2000, dt: 0.05,\n                                        minX: 0, maxX: 1800, maxY: 1000, floorY: 0, size: 200)\n        precondition(ceiling.y + 200 == 1000 && ceiling.vy < 0, \"top edge bounces downward\")\n    }\n    // 系统通知门控 + 配置解析（不触真实通知与真实配置文件）\n    precondition(SystemNotify.gate(\"permission.required\", petHidden: true, mode: \"auto\"))\n    precondition(!SystemNotify.gate(\"permission.required\", petHidden: false, mode: \"auto\"))\n    precondition(!SystemNotify.gate(\"turn.ended\", petHidden: true, mode: \"always\"))\n    precondition(!SystemNotify.gate(\"task.completed\", petHidden: true, mode: \"off\"))\n    precondition(PetConfig.notifyMode([\"notifications\":\"always\"]) == \"always\")\n    precondition(PetConfig.notifyMode([\"notifications\":\"yolo\"]) == \"auto\")\n    precondition(PetConfig.notifyMode([:]) == \"auto\")\n    precondition(PetConfig.position([\"position\":[\"x\":10.0,\"y\":20.0,\"cs\":\"cocoa\"]]) != nil)\n    precondition(PetConfig.position([\"position\":[\"x\":10.0,\"y\":20.0,\"cs\":\"topleft\"]]) == nil)\n    precondition(PetConfig.position([:]) == nil)\n    // 更新检查：版本解析/比较与跳转 tag 提取（与 tests/test_update_check.py 同语义）\n    precondition(UpdateCheck.parseVersion(\"v1.0.1\") == [1,0,1])\n    precondition(UpdateCheck.isNewer(UpdateCheck.parseVersion(\"1.0.10\")!, UpdateCheck.parseVersion(\"1.0.9\")!))\n    precondition(UpdateCheck.isNewer([1,0,2], [1,0,1]))\n    precondition(!UpdateCheck.isNewer([1,0,1], [1,0,1]))\n    precondition(!UpdateCheck.isNewer([1,0], [1,0,0]))\n    precondition(UpdateCheck.isNewer([1,1], [1,0,9]))\n    precondition(UpdateCheck.parseVersion(\"bad\") == nil && UpdateCheck.parseVersion(\"\") == nil)\n    precondition(UpdateCheck.tag(from: URL(string:\"https://github.com/IvenKooLab/desktop-pet/releases/tag/v1.0.1\")!) == \"1.0.1\")\n    precondition(UpdateCheck.tag(from: URL(string:\"https://github.com/IvenKooLab/desktop-pet/releases\")!) == nil)\n    precondition(PetConfig.updateCheckEnabled([:]))\n    precondition(PetConfig.updateCheckEnabled([\"update_check\":\"auto\"]))\n    precondition(!PetConfig.updateCheckEnabled([\"update_check\":\"off\"]))\n    print(\"PASS: upward/downward screen-coordinate drag, timed frame boundaries/wrap, host-bridge reduction\")\n    exit(0)\n}\n\nlet lockPath = NSTemporaryDirectory()+\"comi-desktop-pet-\\(getuid()).lock\"\nlet lockFD = open(lockPath,O_CREAT|O_RDWR,0o600)\nif lockFD < 0 || flock(lockFD,LOCK_EX|LOCK_NB) != 0 {\n    print(\"Comi Pet independent app is already running.\")\n    exit(0)\n}\nlet supplied = CommandLine.arguments.dropFirst().first\nlet environment = ProcessInfo.processInfo.environment[\"PET_FRAMES_DIR\"]\nlet resources = Bundle.main.resourceURL?.appendingPathComponent(\"frames3d\")\nlet fallback = URL(fileURLWithPath:FileManager.default.currentDirectoryPath).appendingPathComponent(\"frames3d\")\nlet directory = supplied.map { URL(fileURLWithPath:$0) }\n    ?? environment.map { URL(fileURLWithPath:$0) }\n    ?? ((resources != nil && FileManager.default.fileExists(atPath:resources!.path)) ? resources! : fallback)\ndo {\n    let controller = try PetController(directory:directory)\n    let app = NSApplication.shared\n    app.setActivationPolicy(.accessory)\n    app.delegate = controller\n    app.run()\n    withExtendedLifetime(controller) {}\n} catch {\n    fputs(\"Comi Pet: \\(error.localizedDescription)\\n\",stderr)\n    exit(1)\n}\n"
    },
    {
      "path": "adapters/dsh/comi-bridge/web.js",
      "content": "/** DSH web overlay host half. Reuses the repository's approved PNG assets.\n * The event inbox is single-consumer, so the overlay keeps its own reducer and\n * never removes files that the standalone app still needs to consume.\n */\nimport { readFileSync, writeFileSync, renameSync, mkdirSync } from 'node:fs'\nimport { dirname, resolve, basename } from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport { appendFileSync } from 'node:fs'\nimport { isTrustedApiRequest } from './trust-fence.js'\n\nfunction note(stage, error) {\n  try { appendFileSync(resolve(dirname(fileURLToPath(import.meta.url)), '../../../.comi-debug.log'),\n    `${new Date().toISOString()} ${stage}: ${error?.stack || error}\\n`) } catch { /* 调试通道失败不影响服务 */ }\n}\n\nexport const PREFIX = '/comi-pet'\nexport const CODE_VERSION = 'fix-webruntime-1'\nexport const LEASE_MS = 60_000\nconst ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../../..')\nconst clean = (value, limit = 80) => typeof value === 'string'\n  ? value.replace(/[\\x00-\\x1f\\x7f]/g, ' ').trim().slice(0, limit) : ''\n\nexport function readDisplay(path, now = Date.now()) {\n  try {\n    const value = JSON.parse(readFileSync(path, 'utf8'))\n    if (value?.version === 1 && value.owner === 'dsh' && value.mode === 'embedded'\n      && Number.isFinite(value.lease_until) && value.lease_until > now && value.lease_until <= now + 90_000) {\n      return { version: 1, owner: 'dsh', mode: 'embedded', lease_until: value.lease_until,\n        client_id: clean(value.client_id, 96) || null }\n    }\n  } catch { /* absent/corrupt/expired means standalone stays visible */ }\n  return { version: 1, owner: 'dsh', mode: 'desktop', lease_until: 0, client_id: null }\n}\n\nconst LANGUAGES = ['system', 'zh', 'en']\nexport function readLanguage(path) {\n  try {\n    const value = readFileSync(path, 'utf8').trim()\n    return LANGUAGES.includes(value) ? value : 'system'\n  } catch { return 'system' }\n}\nexport function writeLanguage(path, value) {\n  mkdirSync(dirname(path), { recursive: true })\n  writeFileSync(path, `${value}\\n`)\n  return value\n}\n\nexport function writeDisplay(path, mode, clientId, now = Date.now()) {\n  const value = { version: 1, owner: 'dsh', mode, lease_until: mode === 'embedded' ? now + LEASE_MS : 0,\n    client_id: mode === 'embedded' ? clientId : null }\n  mkdirSync(dirname(path), { recursive: true })\n  const tmp = `${path}.tmp-${process.pid}-${Math.random().toString(16).slice(2)}`\n  writeFileSync(tmp, JSON.stringify(value))\n  renameSync(tmp, path)\n  return value\n}\n\nexport function reduceSession(sessions, id, event, label, now = Date.now()) {\n  const session = sessions.get(id) ?? { phase: 'idle', label: '', tool: '', updated: now, phaseSince: now, order: 0, id }\n  const previousPhase = session.phase\n  session.updated = now\n  session.order++\n  if (event.kind === 'turn.started') Object.assign(session, { phase: 'working', label: '', tool: '' })\n  if (label) session.label = clean(label)\n  if (event.kind === 'tool.started') Object.assign(session, { phase: 'working', tool: clean(event.toolName, 48) })\n  if (event.kind === 'permission.required') session.phase = 'waiting'\n  if (event.kind === 'tool.finished') session.phase = 'working'\n  if (['turn.ended', 'task.completed', 'turn.failed', 'interrupted', 'session.ended'].includes(event.kind)) {\n    session.phase = event.kind === 'task.completed' ? 'success' : event.kind === 'turn.failed' ? 'failed' : 'idle'\n    session.tool = ''\n  }\n  if (session.phase !== previousPhase || event.kind === 'turn.started') session.phaseSince = now\n  sessions.set(id, session)\n  for (const [key, value] of sessions) if (now - value.updated > 1_200_000) sessions.delete(key)\n}\n\nexport function currentSession(sessions, now = Date.now()) {\n  const all = [...sessions.values()].filter(s => now - s.updated <= 900_000)\n  all.sort((a, b) => Number(b.phase === 'waiting') - Number(a.phase === 'waiting') || b.updated - a.updated)\n  const active = all.find(s => ['working', 'waiting'].includes(s.phase))\n  const selected = active ?? all[0]\n  if (!selected) return { phase: 'idle', label: '', tool: '' }\n  if (['success', 'failed'].includes(selected.phase) && now - selected.updated > 7_000) {\n    return { phase: 'idle', label: '', tool: '' }\n  }\n  return { phase: selected.phase, label: selected.label, tool: selected.tool,\n    session_id: selected.id, phase_since: selected.phaseSince }\n}\n\nfunction json(res, code, value) {\n  res.writeHead(code, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' })\n  res.end(JSON.stringify(value))\n}\n\nasync function readBody(req) {\n  return new Promise((resolveBody, reject) => {\n    let text = '', exceeded = false\n    req.on('data', chunk => {\n      if (exceeded) return\n      text += chunk.toString('utf8')\n      if (text.length > 4096) { exceeded = true; text = ''; reject(new Error('body too large')) }\n    })\n    req.on('end', () => {\n      if (exceeded) return\n      try { resolveBody(JSON.parse(text || '{}')) } catch { reject(new Error('invalid JSON')) }\n    })\n    req.on('error', reject)\n  })\n}\n\nexport function createRouteHandler({ eventsDir, root = ROOT, sessions = new Map(), trustedHosts = () => [], clock = Date.now }) {\n  const displayPath = resolve(dirname(eventsDir), 'display.json')\n  const languagePath = resolve(dirname(eventsDir), 'language')\n  const manifestPath = resolve(root, 'frames3d/animation.json')\n  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'))\n  let version = null\n  try { version = readFileSync(resolve(root, 'VERSION'), 'utf8').trim() } catch { /* 打包目录外跳过 */ }\n  // 桌面端运行时合成的 FALL/LAND 帧也在服务白名单里（与 client.js 的合成剪辑一致）\n  const frames = new Set([...Object.values(manifest.clips).flatMap(clip => clip.frames), 'fall_0', 'land_0'])\n  return async function handler(req, res) {\n    if (!isTrustedApiRequest(req, trustedHosts())) return json(res, 403, { ok: false, error: 'forbidden' })\n    const path = new URL(req.url ?? '/', 'http://dsh.internal').pathname\n    if (req.method === 'GET' && path === `${PREFIX}/api/state`) {\n      return json(res, 200, { ok: true, display: readDisplay(displayPath, clock()), state: currentSession(sessions, clock()),\n        language: readLanguage(languagePath), version })\n    }\n    if (req.method === 'POST' && path === `${PREFIX}/api/language`) {\n      let body\n      try { body = await readBody(req) } catch { return json(res, 400, { ok: false, error: 'invalid body' }) }\n      const value = clean(body?.value, 16)\n      if (!LANGUAGES.includes(value)) return json(res, 400, { ok: false, error: 'invalid language' })\n      writeLanguage(languagePath, value)\n      return json(res, 200, { ok: true, language: value })\n    }\n    if (req.method === 'GET' && path === `${PREFIX}/api/manifest`) return json(res, 200, manifest)\n    if (req.method === 'GET' && path === `${PREFIX}/api/behaviors`) {\n      try { return json(res, 200, JSON.parse(readFileSync(resolve(root, 'animation_behaviors.json'), 'utf8'))) }\n      catch { return json(res, 200, { version: 1, actions: {} }) }\n    }\n    if (req.method === 'GET' && path.startsWith(`${PREFIX}/frames/`)) {\n      const file = path.slice(`${PREFIX}/frames/`.length)\n      const name = file.endsWith('.png') ? file.slice(0, -4) : ''\n      if (!name || basename(file) !== file || !frames.has(name)) return json(res, 404, { ok: false, error: 'unknown frame' })\n      try {\n        const data = readFileSync(resolve(root, 'frames3d', file))\n        res.writeHead(200, { 'content-type': 'image/png', 'cache-control': 'public, max-age=3600' })\n        return res.end(data)\n      } catch { return json(res, 404, { ok: false, error: 'missing frame' }) }\n    }\n    if (req.method === 'POST' && [`${PREFIX}/api/display`, `${PREFIX}/api/heartbeat`].includes(path)) {\n      let body\n      try { body = await readBody(req) } catch { return json(res, 400, { ok: false, error: 'invalid body' }) }\n      const clientId = clean(body?.client_id, 96)\n      if (!/^[a-zA-Z0-9_-]{8,96}$/.test(clientId)) return json(res, 400, { ok: false, error: 'invalid client id' })\n      const current = readDisplay(displayPath, clock())\n      const heartbeat = path.endsWith('/heartbeat')\n      if (heartbeat && (current.mode !== 'embedded' || (current.client_id && current.client_id !== clientId))) {\n        return json(res, 409, { ok: false, display: current, error: 'lease not owned' })\n      }\n      if (!heartbeat && !['embedded', 'desktop'].includes(body.mode)) return json(res, 400, { ok: false, error: 'invalid mode' })\n      // Explicit mode selection can take over; an ordinary heartbeat cannot.\n      const display = writeDisplay(displayPath, heartbeat ? 'embedded' : body.mode, clientId, clock())\n      return json(res, 200, { ok: true, display })\n    }\n    return json(res, 404, { ok: false, error: 'not found' })\n  }\n}\n\nexport function createWebIntegration(ctx, options) {\n  const sessions = new Map()\n  if (typeof ctx.inject === 'function') ctx.inject(['webServer'], wctx => {\n    wctx.effect(() => {\n      // cordis 服务代理对未 inject 的服务读取会抛错（可选链拦不住），\n      // 所以这里 try/catch 后回退空数组：本机 loopback 本来就放行，\n      // trustedHosts 只在局域网部署时才需要。\n      const safeTrustedHosts = () => {\n        try {\n          const list = wctx.webRuntime?.trustedHosts\n          return Array.isArray(list) ? list : []\n        } catch { return [] }\n      }\n      let handler\n      try {\n        handler = createRouteHandler({ ...options, sessions, trustedHosts: safeTrustedHosts })\n      } catch (error) {\n        note('构造失败', error); throw error\n      }\n      // 宿主会把 handler 异常吞成裸 400（空 body），这里兜一层：落盘并回 500 带原因\n      const guarded = async (req, res) => {\n        try {\n          return await handler(req, res)\n        } catch (error) {\n          note('处理异常', error)\n          try { return json(res, 500, { ok: false, version: CODE_VERSION, error: String(error?.stack || error).slice(0, 500) }) }\n          catch { res.destroy() }\n        }\n      }\n      wctx.webServer.register({\n        kind: 'prefix', path: PREFIX, handler: guarded,\n      }, 'comi-bridge: approved pet frames and display lease')\n    })\n  })\n  return { record: (id, event, label) => reduceSession(sessions, id, event, label) }\n}\n"
    },
    {
      "path": "adapters/dsh/comi-bridge/package.json",
      "content": "{\n  \"name\": \"comi-bridge\",\n  \"version\": \"0.2.0\",\n  \"license\": \"MIT\",\n  \"description\": \"Comi pet for DSH: session status, in-app overlay and standalone desktop handoff\",\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"exports\": {\n    \".\": \"./index.js\",\n    \"./client\": \"./client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"engines\": {\n    \"node\": \">=20\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\"@deepseek-ai/dsh-client-ui-slots\"]\n    }\n  }\n}\n"
